    44	namespace   // Private.
    45	{
    46	
    47	enum ColorMode {
    48	    CM_BITMAP = 0,
    49	    CM_GRAYSCALE = 1,
    50	    CM_INDEXED = 2,
    51	    CM_RGB = 3,
    52	    CM_CMYK = 4,
    53	    CM_MULTICHANNEL = 7,
    54	    CM_DUOTONE = 8,
    55	    CM_LABCOLOR = 9
    56	};
    57	
    58	struct PSDHeader {
    59	    uint signature;
    60	    ushort version;
    61	    uchar reserved[6];
    62	    ushort channel_count;
    63	    uint height;
    64	    uint width;
    65	    ushort depth;
    66	    ushort color_mode;
    67	};
    68	
    69	static QDataStream &operator>> (QDataStream &s, PSDHeader &header)
    70	{
    71	    s >> header.signature;
    72	    s >> header.version;
    73	    for (int i = 0; i < 6; i++) {
    74	        s >> header.reserved[i];
    75	    }
    76	    s >> header.channel_count;
    77	    s >> header.height;
    78	    s >> header.width;
    79	    s >> header.depth;
    80	    s >> header.color_mode;
    81	    return s;
    82	}
    83	
    84	// Check that the header is a valid PSD.
    85	static bool IsValid(const PSDHeader &header)
    86	{
    87	    if (header.signature != 0x38425053) {    // '8BPS'
    88	        return false;
    89	    }
    90	    return true;
    91	}
    92	
    93	// Check that the header is supported.
    94	static bool IsSupported(const PSDHeader &header)
    95	{
    96	    if (header.version != 1) {
    97	        return false;
    98	    }
    99	    if (header.channel_count > 16) {
   100	        return false;
   101	    }
   102	    if (header.depth != 8) {
   103	        return false;
   104	    }
   105	    if (header.color_mode != CM_RGB) {
   106	        return false;
   107	    }
   108	    return true;
   109	}
