   238	bool PSDHandler::read(QImage *image)
   239	{
   240	    QDataStream s(device());
   241	    s.setByteOrder(QDataStream::BigEndian);
   242	
   243	    PSDHeader header;
   244	    s >> header;
   245	
   246	    // Check image file format.
   247	    if (s.atEnd() || !IsValid(header)) {
   248	//         qDebug() << "This PSD file is not valid.";
   249	        return false;
   250	    }
   251	
   252	    // Check if it's a supported format.
   253	    if (!IsSupported(header)) {
   254	//         qDebug() << "This PSD file is not supported.";
   255	        return false;
   256	    }
   257	
   258	    QImage img;
   259	    if (!LoadPSD(s, header, img)) {
   260	//         qDebug() << "Error loading PSD file.";
   261	        return false;
   262	    }
   263	
   264	    *image = img;
   265	    return true;
   266	}
   267	
   268	bool PSDHandler::canRead(QIODevice *device)
   269	{
   270	    if (!device) {
   271	        qWarning("PSDHandler::canRead() called with no device");
   272	        return false;
   273	    }
   274	
   275	    qint64 oldPos = device->pos();
   276	
   277	    char head[4];
   278	    qint64 readBytes = device->read(head, sizeof(head));
   279	    if (readBytes != sizeof(head)) {
   280	        if (device->isSequential()) {
   281	            while (readBytes > 0) {
   282	                device->ungetChar(head[readBytes-- - 1]);
   283	            }
   284	        } else {
   285	            device->seek(oldPos);
   286	        }
   287	        return false;
   288	    }
   289	
   290	    if (device->isSequential()) {
   291	        while (readBytes > 0) {
   292	            device->ungetChar(head[readBytes-- - 1]);
   293	        }
   294	    } else {
   295	        device->seek(oldPos);
   296	    }
   297	
   298	    return qstrncmp(head, "8BPS", 4) == 0;
   299	}
