   301	QImageIOPlugin::Capabilities PSDPlugin::capabilities(QIODevice *device, const QByteArray &format) const
   302	{
   303	    if (format == "psd") {
   304	        return Capabilities(CanRead);
   305	    }
   306	    if (!format.isEmpty()) {
   307	        return {};
   308	    }
   309	    if (!device->isOpen()) {
   310	        return {};
   311	    }
   312	
   313	    Capabilities cap;
   314	    if (device->isReadable() && PSDHandler::canRead(device)) {
   315	        cap |= CanRead;
   316	    }
   317	    return cap;
   318	}
